<template><section><h3>Original metadata coverage and categories</h3><div class="integration-toolbar"><select v-model="omics" aria-label="Metadata layer"><option value="genome">Genome</option><option value="transcriptome">RNA</option><option value="proteome">Protein</option></select><select v-model="field" aria-label="Metadata field"><option value="">Field directory</option><option v-for="r in directory" :key="r.field" :value="r.field">{{ r.field }}</option></select><span>{{ result?.total??'…' }} {{ field?'categories':'metadata fields' }}</span></div><p v-if="error">{{ error }}</p><div class="integration-scroll"><table class="table"><thead><tr><th v-for="k in columns" :key="k">{{ k }}</th></tr></thead><tbody><tr v-for="(r,i) in result?.items||[]" :key="i"><td v-for="k in columns" :key="k">{{ r[k] }}</td></tr></tbody></table></div><div class="integration-toolbar"><button class="btn subtle" :disabled="page===1" @click="page--">Previous metadata</button><span>Page {{ page }}</span><button class="btn subtle" :disabled="page*12>=result?.total" @click="page++">Next metadata</button></div></section></template>
<script setup>
import {ref,watch,computed,onMounted} from 'vue';const props=defineProps({context:Object});const omics=ref('genome'),field=ref(''),directory=ref([]),result=ref(null),page=ref(1),error=ref('');let seq=0,catalogSeq=0
const columns=computed(()=>Object.keys(result.value?.items?.[0]||{}))
async function load(){const s=++seq;try{const r=await props.context.get('metadata/',{omics:omics.value,field:field.value||undefined,page:page.value,page_size:12});if(s===seq){result.value=r;error.value=''}}catch(e){if(s===seq)error.value=e.message}}
async function catalog(){const seq=++catalogSeq,layer=omics.value,version=props.context.manifest.value?.artifact_version;directory.value=[];const rows=[];let total=1;for(let page=1;rows.length<total;page++){const r=await props.context.get('metadata/',{omics:layer,page,page_size:12});if(seq!==catalogSeq||layer!==omics.value||version!==props.context.manifest.value?.artifact_version)return;total=r.total;rows.push(...r.items)}if(seq===catalogSeq)directory.value=rows}
watch(()=>props.context.manifest.value?.artifact_version,()=>{result.value=null;catalog();load()})
watch(omics,()=>{field.value='';page.value=1;catalog();load()});watch(field,()=>{page.value=1;load()});watch(page,load);onMounted(()=>{catalog();load()})
</script>
